mapper.select:
SELECT ca.*,
       COALESCE(NULLIF(su.nick_name, ''), su.user_name) AS added_by_name,
       mt.contact_wechat AS contact_wechat

LEFT JOIN sys_user su
    ON su.user_id = mt.owner_user_id

    ca.del_flag = '0'

        AND ca.tenant_id = #{query.tenantId}


        AND ca.platform = #{query.platform}


        AND ca.platform_creator_id = #{query.platformCreatorId}


        AND ca.nickname LIKE CONCAT('%', #{query.nickname}, '%')


        AND ca.profile_status = #{query.profileStatus}


ORDER BY mt.update_time DESC, ca.update_time DESC
